<?php declare(strict_types=1);
namespace Modules\PromptEngine\Services;
use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str; use RuntimeException; use Modules\PromptEngine\Services\ImageProviders\{ChatGptImageProvider,GeminiImageProvider};
final class ImageGenerationService { public function __construct(private GeminiImageProvider $gemini,private ChatGptImageProvider $openai){} public function generate(string $provider,string $prompt,string $ratio):array{if(!config('promptengine.config.image_generation.enabled'))return ['provider'=>$provider,'status'=>'skipped','reason'=>'Image generation is disabled.'];$driver=match($provider){'gemini'=>$this->gemini,'chatgpt-image'=>$this->openai,default=>throw new RuntimeException('This platform has no image generation provider.')};$raw=$driver->generate($prompt,$ratio);$bytes=$raw['bytes']??false;$mime=$raw['mime_type']??'';if(!is_string($bytes)||$bytes===''||strlen($bytes)>config('promptengine.config.image_generation.max_bytes')||!in_array($mime,['image/png','image/jpeg','image/webp'],true))throw new RuntimeException('Provider returned an invalid image.');$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime];$path=trim(config('promptengine.config.image_generation.directory'),'/').'/'.Str::uuid().'.'.$ext;$disk=config('promptengine.config.image_generation.disk');Storage::disk($disk)->put($path,$bytes);$size=@getimagesizefromstring($bytes);return ['provider'=>$provider,'status'=>'completed','path'=>$path,'url'=>Storage::disk($disk)->url($path),'mime_type'=>$mime,'width'=>$size[0]??null,'height'=>$size[1]??null];} }
